import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`start-a-franchise`,heroTitle:`Franchise research in minutes`,heroSubtitle:`Perplexity Computer researches franchises, compares costs, and builds your launch plan — automatically.`,inputUrlCta:`Evaluate this franchise`,inputUrlPlaceholder:`Enter franchise name`,inputUrlPrefill:`Go to {url} and do a full evaluation of this franchise opportunity. Research the brand, its franchise model, fees, and requirements. Then: 1) Summarize the franchise concept, initial investment range, ongoing royalties, and territory details. 2) Analyze the competitive landscape — who are the top 5 competitors in this space and how does this franchise compare? 3) Estimate startup costs including franchise fee, buildout, equipment, working capital, and first-year operating expenses. 4) Build a 12-month financial projection with revenue assumptions, break-even timeline, and cash flow forecast. 5) Create a 90-day launch checklist covering entity formation, financing, site selection, permits, hiring, and grand opening marketing. 6) List the top risks and red flags to investigate before signing the franchise agreement.`,heroOverlaySteps:[`Researching the franchise brand, fees, and territory model`,`Analyzing competitors and market positioning in this franchise category`,`Building startup cost estimates and 12-month financial projections`,`Launch checklist, risk analysis, and financial plan — ready to review`],generatingSteps:[`Visiting {url} to extract franchise details, fees, and requirements`,`Designing an agent to research competitors and market opportunity in this space`,`Configuring financial modeling for startup costs, cash flow, and break-even analysis`,`Setting up your 90-day launch checklist and risk assessment framework`],featureSectionTitle:`From franchise URL to launch plan`,featureCardTitles:[`Connects to your business stack`,`Outputs you can act on`],featureCardDescriptions:[`Computer breaks your project into tasks, spins up specialized agents, and matches each one to the AI model that does it best.`,`Google Sheets, Notion, Gmail, QuickBooks, Slack — Computer plugs into your tools so financial models, checklists, and outreach happen in one workflow.`,`Franchise comparison reports. Startup cost breakdowns. 12-month financial projections. 90-day launch checklists. Computer delivers work you can take to your accountant or lender.`],capabilitySectionTitle:`Your franchise advisor, on autopilot`,capabilitySectionSubtitle:`Paste a franchise URL, step away, come back to a complete evaluation and launch plan.`,capabilityCards:[{title:`Franchise Research`,description:`Computer can analyze any franchise — fees, territory rules, FDD highlights, franchisee reviews — and deliver a structured evaluation backed by sources.`},{title:`Financial Modeling`,description:`Computer can estimate startup costs, project monthly cash flow, and calculate break-even timelines — tailored to your market and investment level.`},{title:`Competitive Analysis`,description:`Computer can map the competitive landscape — compare franchise brands, market saturation, and unit economics side by side.`},{title:`Connect Your Tools`,description:`Computer can read and write to Google Sheets, Notion, Gmail, QuickBooks, and more — build workflows across your entire business stack.`},{title:`Remember & Learn`,description:`Computer can remember your budget, location preferences, and franchise criteria across sessions — so every evaluation builds on what came before.`},{title:`Monitor & Alert`,description:`Computer can watch franchise listings and industry news — set up a monitoring workflow that pings you when new opportunities match your criteria.`}]});export{t as default};
